import Link from 'next/link';
import { notFound } from 'next/navigation';
import { getPublishedPosts, getPostBySlug, formatDate } from '@/lib/posts';

export async function generateStaticParams() {
  const posts = await getPublishedPosts();
  return posts.map((post) => ({ slug: post.slug }));
}

export default async function ResourceArticlePage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const post = await getPostBySlug(slug);

  if (!post) notFound();

  const related = (await getPublishedPosts())
    .filter((item) => item.category === post.category && item.slug !== post.slug)
    .slice(0, 3);

  return (
    <div className="article-page">
      <div className="container article-shell">
        <div className="article-hero">
          <img src={post.featured_image} alt={post.title} />
        </div>

        <article className="article-body">
          <p className="eyebrow">{post.category}</p>
          <h1 style={{ fontSize: 'clamp(2.4rem, 5vw, 4rem)', marginTop: 18 }}>{post.title}</h1>
          <div className="meta-row">
            <span>By {post.author}</span>
            <span>{formatDate(post.published_at)}</span>
          </div>
          <div dangerouslySetInnerHTML={{ __html: post.body }} />
          <div style={{ marginTop: 28, display: 'flex', gap: 14, flexWrap: 'wrap' }}>
            <Link href="/resources" target="_blank" rel="noreferrer" className="secondary-btn">← Back to all resources</Link>
          </div>
        </article>

        {related.length > 0 && (
          <div style={{ marginTop: 18 }}>
            <p className="eyebrow">Related articles</p>
            <div className="related-grid" style={{ gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', marginTop: 20 }}>
              {related.map((item) => (
                <Link key={item.id} href={`/resources/${item.slug}`} target="_blank" rel="noreferrer" className="related-card" style={{ padding: 20 }}>
                  <div className="resource-date">{item.category}</div>
                  <h3 style={{ margin: '0 0 12px' }}>{item.title}</h3>
                  <span>Read article ↗</span>
                </Link>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
